// Demo: UEFI Variable Storage — CRC integrity check
function crc(s){var c=0xFFFF;for(var i=0;i<s.length;i++){c^=s.charCodeAt(i);for(var b=0;b<8;b++){c=(c&1)?(c>>>1)^0xA001:c>>>1;}}return c.toString(16);}
var data='nvram-state-1';var sum=crc(data);
console.log('technique: UEFI Variable Storage');console.log('stored CRC: '+sum+', recomputed: '+crc(data));
console.log(sum===crc(data)?'integrity OK':'CORRUPT — restore from backup');

// Demo: Battery-Backed SRAM — journaled write atomicity
var store={},journal=[];
function write(k,v){journal.push({k:k,v:v});store[k]=v;journal.pop();}
write('config',8);write('counter',15);
console.log('technique: Battery-Backed SRAM');console.log('journal entries pending: '+journal.length);
console.log(journal.length===0?'all writes committed atomically':'RECOVERY NEEDED — replay journal');
console.log('state: '+JSON.stringify(store));

// Demo: MRAM and FRAM — wear leveling distribution
var cells=new Array(8).fill(0);
for(var i=0;i<16*10;i++){var c=0;for(var j=1;j<8;j++){if(cells[j]<cells[c])c=j;}cells[c]++;}
console.log('technique: MRAM and FRAM');console.log('writes per cell: '+cells.join(', '));
console.log('max/min ratio: '+(Math.max.apply(null,cells)/Math.min.apply(null,cells)).toFixed(2)+' — leveling spreads wear');

